"""Add section anchors and section menus to every project page.

Each page gets two menus built from its h2/h3 headings:
  - an inline "Contents" block under the byline (narrow screens and print)
  - a sticky sidebar in the left margin that highlights the section in view (wide screens)

Run from the portfolio folder after adding or renaming sections:
    python add_toc.py
Safe to rerun: existing menus, anchors, styles and script are replaced.
"""
import re
from pathlib import Path

PAGES = ["1", "2", "3a", "3b", "4"]

CSS = """
  /* section menus (generated by add_toc.py) */
  nav.toc {
    border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule);
    padding: 14px 0 16px; margin: 0 0 8px; font-size: .92rem;
  }
  nav.toc .label {
    display: block; font-size: .72rem; letter-spacing: .08em; text-transform: uppercase;
    color: var(--muted); margin-bottom: 8px; font-family: var(--mono);
  }
  nav.toc .group { color: var(--ink); font-weight: 600; margin: 10px 0 4px; }
  nav.toc .group:first-of-type { margin-top: 0; }
  nav.toc ol { list-style: none; margin: 0; padding: 0;
               display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 2px 20px; }
  nav.toc a { color: #7a2b1d; text-decoration: none; }
  nav.toc a:hover { text-decoration: underline; }
  nav.toc .n { font-family: var(--mono); font-size: .8rem; color: var(--muted); margin-right: 6px; }
  h2[id], h3[id] { scroll-margin-top: 20px; }
  nav.toc + h2.part { border-top: 0; padding-top: 0; margin-top: 44px; }

  nav.side { display: none; }
  @media (min-width: 1280px) {
    nav.toc { display: none; }
    nav.toc + h2.part { margin-top: 0; }
    nav.side {
      display: block; position: fixed; top: 64px;
      left: calc(50% - 390px - 250px); width: 220px;
      max-height: calc(100vh - 96px); overflow-y: auto;
      font-size: .8rem; line-height: 1.4;
    }
    nav.side .group {
      font-size: .68rem; letter-spacing: .08em; text-transform: uppercase;
      color: var(--muted); font-family: var(--mono); margin: 14px 0 4px 12px;
    }
    nav.side .group:first-child { margin-top: 0; }
    nav.side ol { list-style: none; margin: 0; padding: 0; }
    nav.side a {
      display: block; padding: 3px 0 3px 12px; border-left: 2px solid var(--rule);
      color: var(--muted); text-decoration: none;
    }
    nav.side a.sub { padding-left: 24px; }
    nav.side a:hover { color: var(--ink); }
    nav.side a.active { color: #7a2b1d; border-left-color: #7a2b1d; }
    nav.side .n { font-family: var(--mono); font-size: .74rem; margin-right: 6px; }
  }
  @media print { nav.side { display: none; } nav.toc { display: block; } }
  /* end section menus */
"""

SCRIPT = """<script id="toc-spy">
(function () {
  var links = Array.prototype.slice.call(document.querySelectorAll("nav.side a"));
  var targets = links.map(function (a) { return document.getElementById(a.getAttribute("href").slice(1)); });
  function update() {
    var line = window.innerHeight * 0.3, current = 0;
    for (var i = 0; i < targets.length; i++) {
      if (targets[i] && targets[i].getBoundingClientRect().top <= line) current = i;
    }
    if (window.innerHeight + window.scrollY >= document.body.scrollHeight - 2) current = targets.length - 1;
    links.forEach(function (a, i) { a.classList.toggle("active", i === current); });
  }
  var ticking = false;
  window.addEventListener("scroll", function () {
    if (!ticking) { ticking = true; requestAnimationFrame(function () { ticking = false; update(); }); }
  }, { passive: true });
  window.addEventListener("resize", update);
  update();
})();
</script>"""

NUM = re.compile(r"^(?:Part\s+)?([A-Z]\.\d+(?:\.\d+)*|\d+(?:\.\d+)*)[:\s]\s*(.*)$")


def slug(text):
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def strip_tags(s):
    return re.sub(r"<[^>]+>", "", s).replace("&amp;", "&").strip()


def short_group(title):
    """'Part A: Image Warping and Mosaicing' -> 'Part A'."""
    return title.split(":")[0]


def process(path):
    html = path.read_text()

    # remove anything generated by a previous run
    html = re.sub(r"\n?<nav class=\"(?:toc|side)\"[^>]*>.*?</nav>\n", "\n", html, flags=re.S)
    html = re.sub(r"\n?<script id=\"toc-spy\">.*?</script>\n?", "\n", html, flags=re.S)
    html = re.sub(r"\n  /\* section menus.*?/\* end section menus \*/\n", "\n", html, flags=re.S)
    html = re.sub(r"\n  nav\.toc \{.*?nav\.toc \+ h2\.part \{[^}]*\}\n", "\n", html, flags=re.S)  # pre-marker version
    html = html.replace("</style>", CSS.strip("\n") + "\n</style>", 1)

    used, groups = set(), []          # groups: [(group title or None, [(num, title, id, is_sub)])]
    numbered_h2 = any(NUM.match(strip_tags(m)) for m in re.findall(r"<h2[^>]*>(.*?)</h2>", html))

    def tag(m):
        level, attrs, inner = m.group(1), m.group(2), m.group(3)
        attrs = re.sub(r'\s+id="[^"]*"', "", attrs)
        text = strip_tags(inner)
        num = NUM.match(text)
        hid = slug(num.group(1) if num else text)
        base, k = hid, 2
        while hid in used:
            hid, k = f"{base}-{k}", k + 1
        used.add(hid)
        if 'class="part"' in attrs:
            groups.append((text, []))
        elif level == "2" or (num and numbered_h2 and "." in num.group(1)):
            if not groups:
                groups.append((None, []))
            if num:
                groups[-1][1].append((num.group(1), num.group(2), hid, level == "3"))
            elif level == "2":
                groups[-1][1].append(("", text, hid, False))
        return f'<h{level}{attrs} id="{hid}">{inner}</h{level}>'

    html = re.sub(r"<h([23])([^>]*)>(.*?)</h\1>", tag, html)

    inline = ['<nav class="toc">', '<span class="label">Contents</span>']
    side = ['<nav class="side" aria-label="Sections">']
    for title, items in groups:
        if title:
            inline.append(f'<div class="group">{title}</div>')
            side.append(f'<div class="group">{short_group(title)}</div>')
        inline.append("<ol>")
        side.append("<ol>")
        for num, text, hid, sub in items:
            n = f'<span class="n">{num}</span>' if num else ""
            inline.append(f'  <li><a href="#{hid}">{n}{text}</a></li>')
            cls = ' class="sub"' if sub else ""
            side.append(f'  <li><a{cls} href="#{hid}">{n}{text}</a></li>')
        inline.append("</ol>")
        side.append("</ol>")
    inline.append("</nav>")
    side.append("</nav>")

    html = re.sub(r'(<p class="byline">.*?</p>\n)', lambda m: m.group(1) + "\n" + "\n".join(inline) + "\n",
                  html, count=1, flags=re.S)
    html = html.replace("<body>\n", "<body>\n" + "\n".join(side) + "\n", 1)
    html = html.replace("</body>", SCRIPT + "\n</body>", 1)
    html = re.sub(r"\n{3,}", "\n\n", html)
    path.write_text(html)
    print(path, sum(len(i) for _, i in groups), "links")


for p in PAGES:
    process(Path(p) / "index.html")
